    return switch (shape) {
        case Circle c -> String.format("%.2f", Math.PI * c.radius() * c.radius());
        case Rectangle r -> String.format("%.2f", r.width() * r.height());
        case Triangle t -> String.format("%.2f", 0.5 * t.base() * t.height());
