static BoundingBox boundingBoxOf(Shape shape) {
    return switch (shape) {
        case Circle c -> new BoundingBox(2 * c.radius(), 2 * c.radius());
        case Rectangle r -> new BoundingBox(r.width(), r.height());
        case Triangle t -> new BoundingBox(t.base(), t.height());
    };
}
