static String toInfixString(Expr expr) {
    return switch (expr) {
        case Num(double v) -> String.valueOf(v);
        case Add(Expr l, Expr r) -> "(" + toInfixString(l) + " + " + toInfixString(r) + ")";
        case Multiply(Expr l, Expr r) -> "(" + toInfixString(l) + " * " + toInfixString(r) + ")";
    };
}
Expr expr = new Multiply(new Add(new Num(2), new Num(3)), new Num(4));
System.out.println(toInfixString(expr));

static int depth(Expr expr) {
    return switch (expr) {
        case Num n -> 1;
        case Add(Expr l, Expr r) -> 1 + Math.max(depth(l), depth(r));
        case Multiply(Expr l, Expr r) -> 1 + Math.max(depth(l), depth(r));
    };
}
Expr tree = new Multiply(new Add(new Num(1), new Multiply(new Num(2), new Num(3))), new Num(4));
System.out.println(depth(tree)); // 3

