static String classifyOld(Object o) {
    if (o instanceof String s) return "String: " + s;
    else if (o instanceof Integer i) return "Integer: " + i;
    else if (o instanceof Double d) return "Double: " + d;
    else if (o instanceof java.util.List<?> l) return "Lista: " + l.size();
    else return "nieznany";
}

// Wersja switch pattern matching, 7 linii ale bardziej deklaratywna:
static String classifyNew(Object o) {
    return switch (o) {
        case String s -> "String: " + s;
        case Integer i -> "Integer: " + i;
        case Double d -> "Double: " + d;
        case java.util.List<?> l -> "Lista: " + l.size();
        default -> "nieznany";
    };
}
// Switch grupuje wszystkie przypadki w JEDNYM, spojnym bloku (jedno miejsce dopasowania),
// zamiast rozproszonych warunkow if - latwiej ogarnac wszystkie galezie na pierwszy rzut oka.

static Expr simplify(Expr expr) {
    return switch (expr) {
        case Multiply(Num(double v), Expr r) when v == 0 -> new Num(0);
        case Multiply(Expr l, Num(double v)) when v == 0 -> new Num(0);
        default -> expr;
    };
}
System.out.println(eval(simplify(new Multiply(new Num(0), new Num(99)))));

