// if/else if:
static String oldStyle(Object o) {
    if (o instanceof String s) return "S:" + s;
    else if (o instanceof Integer i) return "I:" + i;
    else if (o instanceof Double d) return "D:" + d;
    else if (o instanceof Boolean b) return "B:" + b;
    else return "?";
}

// switch pattern matching:
static String newStyle(Object o) {
    return switch (o) {
        case String s -> "S:" + s;
        case Integer i -> "I:" + i;
        case Double d -> "D:" + d;
        case Boolean b -> "B:" + b;
        default -> "?";
    };
}
// switch od razu sygnalizuje CZYTELNIKOWI 'to jest jedno dopasowanie na wielu wariantach' -
// if/else if wyglada jak seria NIEZALEZNYCH decyzji, mimo ze de facto tez dotycza tej samej
// zmiennej. switch grupuje logike w jednym, latwym do skanowania bloku.

sealed interface Expr2 permits Num2, Add2, Multiply2, Divide2 {}
record Num2(double value) implements Expr2 {}
record Add2(Expr2 left, Expr2 right) implements Expr2 {}
record Multiply2(Expr2 left, Expr2 right) implements Expr2 {}
record Divide2(Expr2 left, Expr2 right) implements Expr2 {}

static double eval2(Expr2 expr) {
    return switch (expr) {
        case Num2(double v) -> v;
        case Add2(Expr2 l, Expr2 r) -> eval2(l) + eval2(r);
        case Multiply2(Expr2 l, Expr2 r) -> eval2(l) * eval2(r);
        case Divide2(Expr2 l, Expr2 r) when eval2(r) == 0 -> throw new ArithmeticException("dzielenie przez zero");
        case Divide2(Expr2 l, Expr2 r) -> eval2(l) / eval2(r);
    };
}
System.out.println(eval2(new Divide2(new Num2(10), new Num2(2))));

sealed interface BoolExpr permits BoolLit, And, Or, Not {}
record BoolLit(boolean value) implements BoolExpr {}
record And(BoolExpr left, BoolExpr right) implements BoolExpr {}
record Or(BoolExpr left, BoolExpr right) implements BoolExpr {}
record Not(BoolExpr expr) implements BoolExpr {}

static boolean evalBool(BoolExpr expr) {
    return switch (expr) {
        case BoolLit(boolean v) -> v;
        case And(BoolLit(boolean v), BoolExpr other) when !v -> false; // krotkie spiecie
        case And(BoolExpr l, BoolExpr r) -> evalBool(l) && evalBool(r);
        case Or(BoolExpr l, BoolExpr r) -> evalBool(l) || evalBool(r);
        case Not(BoolExpr e) -> !evalBool(e);
    };
}

BoolExpr tree = new Or(new And(new BoolLit(true), new BoolLit(false)), new Not(new BoolLit(false)));
System.out.println(evalBool(tree)); // true
